"""Document chunking utilities (dependency-free)."""

from __future__ import annotations


class RecursiveCharacterTextSplitter:
    """Split text into overlapping chunks using separators in priority order.

    The longest separator that appears before the chunk boundary wins, which
    keeps paragraphs and sentences intact when possible.
    """

    def __init__(
        self,
        chunk_size: int = 500,
        chunk_overlap: int = 80,
        separators: tuple[str, ...] = ("\n\n", "\n", ". ", " "),
    ):
        if chunk_overlap >= chunk_size:
            raise ValueError("chunk_overlap must be smaller than chunk_size")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = tuple(separators)

    def split_text(self, text: str) -> list[str]:
        text = (text or "").strip()
        if not text:
            return []
        if len(text) <= self.chunk_size:
            return [text]

        chunks: list[str] = []
        start = 0
        n = len(text)
        while start < n:
            end = min(start + self.chunk_size, n)
            if end < n:
                best = -1
                for sep in self.separators:
                    idx = text.rfind(sep, start, end)
                    if idx > best:
                        best = idx
                if best > start:
                    end = best + len(sep)
            chunk = text[start:end].strip()
            if chunk:
                chunks.append(chunk)
            if end >= n:
                break
            start = max(end - self.chunk_overlap, start + 1)
        return chunks

"""Lightweight, dependency-free embeddings.

Implements a hashing TF-IDF embedder: tokens plus character n-grams are mapped
deterministically onto a fixed-size vector via a string hash, then weighted with
sublinear TF (1 + log tf) and IDF. Vectors are L2-normalized so cosine similarity
is a simple dot product.

Swap point: in production, replace this with a neural embedding model
(e.g. text-embedding-ada-002 or all-MiniLM-L6-v2) -- the rest of the pipeline
only depends on the ``transform`` / ``cosine_similarity`` contract.
"""

from __future__ import annotations

import math
import re
from collections import Counter

_TOKEN_RE = re.compile(r"[a-z0-9]+")


def tokenize(text: str) -> list[str]:
    """Lowercase alphanumeric tokens."""
    return _TOKEN_RE.findall((text or "").lower())


def _char_ngrams(text: str, n: int) -> list[str]:
    norm = re.sub(r"\s+", " ", (text or "").lower()).strip()
    if len(norm) < n:
        return [norm] if norm else []
    return [norm[i : i + n] for i in range(len(norm) - n + 1)]


class HashingTfidfVectorizer:
    """Deterministic TF-IDF-style vectorizer with feature hashing.

    Attributes:
        dim: number of embedding dimensions (feature-hash space).
        min_df: minimum document frequency for a feature to be kept.
        ngram_range: (min_n, max_n) character n-gram sizes included.
    """

    def __init__(self, dim: int = 8192, min_df: int = 1, ngram_range=(2, 3)):
        self.dim = dim
        self.min_df = min_df
        self.min_n, self.max_n = ngram_range
        self._idf: dict[str, float] = {}
        self._fitted = False
        self._seed = 0x9E3779B9

    # -- internal helpers -------------------------------------------------
    def _features(self, text: str) -> list[str]:
        feats = tokenize(text)
        for n in range(self.min_n, self.max_n + 1):
            feats.extend(_char_ngrams(text, n))
        return feats

    def _hash(self, feature: str) -> int:
        h = self._seed
        for ch in feature:
            h = ((h * 33) ^ ord(ch)) & 0xFFFFFFFF
        return h % self.dim

    # -- API --------------------------------------------------------------
    def fit(self, texts: list[str]) -> "HashingTfidfVectorizer":
        df: Counter[str] = Counter()
        for t in texts:
            df.update(set(self._features(t)))
        total = len(texts)
        for feat, count in df.items():
            if count >= self.min_df:
                self._idf[feat] = math.log((total + 1.0) / (1.0 + count)) + 1.0
        self._fitted = True
        return self

    @property
    def idf(self) -> dict[str, float]:
        return self._idf

    def transform(self, text: str) -> dict[int, float]:
        """Return a normalized sparse vector as {feature_id: weight}."""
        if not self._fitted:
            raise RuntimeError("vectorizer must be fit before transform()")
        counts = Counter(self._features(text))
        vec: dict[int, float] = {}
        for feat, cnt in counts.items():
            weight = self._idf.get(feat)
            if weight is None:
                continue
            tf = 1.0 + math.log(cnt)
            fid = self._hash(feat)
            vec[fid] = vec.get(fid, 0.0) + tf * weight
        norm = math.sqrt(sum(v * v for v in vec.values()))
        if norm:
            vec = {f: v / norm for f, v in vec.items()}
        return vec


def cosine_similarity(a: dict[int, float], b: dict[int, float]) -> float:
    """Cosine similarity between two normalized sparse vectors."""
    if not a or not b:
        return 0.0
    small, large = (a, b) if len(a) <= len(b) else (b, a)
    return sum(v * large[k] for k, v in small.items() if k in large)

"""In-memory vector store with metadata filtering and cosine search."""

from __future__ import annotations

from .embeddings import cosine_similarity

# Supported metadata filter operators.
# Each maps to a callable (actual_value, filter_value) -> bool.
_OPERATORS = {
    "eq": lambda v, x: v == x,
    "ne": lambda v, x: v != x,
    "gt": lambda v, x: v is not None and v > x,
    "gte": lambda v, x: v is not None and v >= x,
    "lt": lambda v, x: v is not None and v < x,
    "lte": lambda v, x: v is not None and v <= x,
    "in": lambda v, x: v in x,
    "nin": lambda v, x: v not in x,
    "exists": lambda v, x: (v is not None) == bool(x),
    "contains": lambda v, x: (
        v is not None and (x in v if isinstance(v, (list, tuple, str)) else False)
    ),
}


def _value(meta: dict, field: str):
    """Read a (possibly dotted) metadata field; missing fields return None."""
    cur = meta
    for part in field.split("."):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return None
    return cur


def match_filter(meta: dict, condition: dict) -> bool:
    """Evaluate one filter condition against a metadata dict.

    Supported shapes:

    1. Field-style:      {"field": "priority", "op": "gte", "value": 4}
    2. Operator-style:   {"priority": {"gte": 4}, "category": "security"}
       (multiple fields are ANDed)

    Raises:
        ValueError: for an unknown operator.
    """
    if isinstance(condition, dict) and set(condition) <= {"field", "op", "value"} and {
        "field",
        "op",
        "value",
    }.issubset(condition):
        op = condition["op"]
        if op not in _OPERATORS:
            raise ValueError(f"unknown metadata operator '{op}'")
        return _OPERATORS[op](_value(meta, condition["field"]), condition["value"])

    for field, spec in condition.items():
        if isinstance(spec, dict) and any(op in _OPERATORS for op in spec):
            for op, val in spec.items():
                if op not in _OPERATORS:
                    raise ValueError(f"unknown metadata operator '{op}'")
                if not _OPERATORS[op](_value(meta, field), val):
                    return False
        elif isinstance(spec, (list, tuple, set)):
            if _value(meta, field) not in spec:
                return False
        else:
            if _value(meta, field) != spec:
                return False
    return True


def apply_filters(meta: dict, filters) -> bool:
    """Apply zero-or-more conditions (a dict, or an AND-list of dicts)."""
    if not filters:
        return True
    if isinstance(filters, dict):
        filters = [filters]
    return all(match_filter(meta, cond) for cond in filters)


class VectorStore:
    """Stores documents + sparse vectors and supports filtered similarity search."""

    def __init__(self, embedder):
        self.embedder = embedder
        self._docs: list[dict] = []

    def __len__(self) -> int:
        return len(self._docs)

    def add(self, text: str, metadata: dict | None = None, doc_id: str | None = None) -> str:
        """Add a document; the vector is computed lazily on first search."""
        rec = {
            "id": doc_id if doc_id is not None else f"doc-{len(self._docs)}",
            "text": text,
            "metadata": dict(metadata or {}),
            "vector": None,
        }
        self._docs.append(rec)
        return rec["id"]

    # -- internals --------------------------------------------------------
    def _vec(self, rec: dict) -> dict[int, float]:
        if rec["vector"] is None:
            rec["vector"] = self.embedder.transform(rec["text"])
        return rec["vector"]

    # -- search -----------------------------------------------------------
    def search(self, query: str, k: int = 5, filters=None) -> list[tuple[float, dict]]:
        """Cosine search restricted by optional metadata filters."""
        qv = self.embedder.transform(query)
        hits: list[tuple[float, dict]] = []
        for rec in self._docs:
            if not apply_filters(rec["metadata"], filters):
                continue
            sim = cosine_similarity(qv, self._vec(rec))
            hits.append((sim, rec))
        hits.sort(key=lambda t: t[0], reverse=True)
        return hits[:k]

